DEFAULT_FILE = "lightning_override.csv"
def find_sample():
    roots=[Path('/kaggle/input/competitions/rogii-wellbore-geology-prediction'), Path('/kaggle/input/rogii-wellbore-geology-prediction')]
    for root in roots:
        p=root/'sample_submission.csv'
        if p.exists(): return pd.read_csv(p)
    for p in Path('/kaggle/input').rglob('sample_submission.csv'):
        return pd.read_csv(p)
    raise FileNotFoundError('sample_submission.csv not found')
work=Path('/kaggle/working') if Path('/kaggle/working').exists() else Path.cwd()
sample=find_sample() if Path('/kaggle/input').exists() else pd.read_csv('data/rogii-wellbore-geology-prediction/sample_submission.csv')
sample_ids=sample['id'].astype(str).tolist()
written=[]
for name,payload in PAYLOADS.items():
    df=pd.read_csv(BytesIO(gzip.decompress(base64.b64decode(payload))))[['id','tvt']]
    df['id']=df['id'].astype(str)
    if df['id'].tolist()!=sample_ids: raise RuntimeError(f'id order mismatch for {name}')
    vals=pd.to_numeric(df['tvt'], errors='coerce').to_numpy(float)
    if not np.isfinite(vals).all(): raise RuntimeError(f'non-finite tvt for {name}')
    df['tvt']=vals
    df.to_csv(work/name, index=False)
    written.append(name)
pd.read_csv(work/DEFAULT_FILE).to_csv(work/'submission.csv', index=False)
with open(work/'static_candidate_manifest.json','w',encoding='utf-8') as f:
    json.dump({'default_file':DEFAULT_FILE,'written':written,'manifest':MANIFEST}, f, indent=2, sort_keys=True)
print(json.dumps({'default_file':DEFAULT_FILE,'n_files':len(written)}, indent=2))
